def final_positions(nums, moveFrom, moveTo):
    # Create a set to store the occupied positions
    occupied_positions = set(nums)

    # Create a set to store the final positions
    final_positions = set()

    # Iterate through the moveFrom and moveTo arrays
    for i in range(len(moveFrom)):
        # Move all marbles from moveFrom[i] to moveTo[i]
        for pos in moveFrom[i]:
            if pos in occupied_positions:
                occupied_positions.remove(pos)
            occupied_positions.add(moveTo[i][pos])

        # Add the final position to the set of occupied positions
        final_positions.add(moveTo[i][pos] for pos in moveFrom[i])

    # Convert the set of final positions to a sorted list
