    count_S = S.count('@')
    count_T = T.count('@')

    # If the number of @s in both strings are different, it's impossible to win
    if count_S != count_T:
        return "No"

    # If the number of @s in both strings are the same, we need to check if we can make the strings equal
    # We can replace the @s in S with any of the characters 'a', 't', 'c', 'o', 'd', 'e', 'r'
    # We can replace the @s in T with any of the characters 'a', 't', 'c', 'o', 'd', 'e', 'r'
    # We need to check if we can make the two strings equal by replacing the @s

    # Create a dictionary to map each character to its possible replacements
    replacements = {
        'a': 'a', 't': 't', 'c': 'c', 'o': 'o', 'd': 'd', 'e': 'e', 'r': 'r'
    }

    # Check if we can make the two strings equal by replacing the @s
    for char in replacements:
        if char in S:
