def max_candy_squares(H, W, T, grid):
    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find start and goal positions
    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)

    # BFS to find the maximum number of candy squares visited
    visited = [[-1 for _ in range(W)] for _ in range(H)]
    queue = [(start[0], start[1], 0, 0)]  # (row, col, moves, candies_visited)
    visited[start[0]][start[1]] = 0

    while queue:
        r, c, moves, candies_visited = queue.pop(0)

        # If we reach the goal, return the number of candies visited
        if (r, c) == goal:
            return candies_visited

        # If we have used up all moves, continue to the next iteration
        if moves >= T:
            continue

        # Explore all possible moves
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#':
                new_candies_visited = candies_visited + (1 if grid[nr][nc] == 'o' else 0)
                if visited[nr][nc] == -1 or visited[nr][nc] < new_candies_visited:
                    visited[nr][nc] = new_candies_visited
                    queue.append((nr, nc, moves + 1, new_candies_visited))

    # If we exhaust the queue without finding the goal, return -1
    return -1

