def count_ways(N, T, M, incompatible_pairs):
    from collections import defaultdict

    # Create a graph where each node is a player and each edge is an incompatible pair
    graph = defaultdict(list)
    for A, B in incompatible_pairs:
        graph[A].append(B)
        graph[B].append(A)

    # Function to perform DFS and count valid divisions
    def dfs(node, parent):
        count = 1
        for neighbor in graph[node]:
            if neighbor != parent:
                count += dfs(neighbor, node)
        return count

    # Count the number of valid divisions
    total_ways = 0
    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            if (i, j) not in graph:
                total_ways += dfs(i, -1) * dfs(j, -1)

    return total_ways

