def min_sum(nums, andValues):
    n = len(nums)
    m = len(andValues)

    # If the total AND of all elements is not equal to the last element, return -1
    total_and = nums[0]
    for num in nums:
        total_and &= num
    if total_and != nums[-1]:
        return -1

    # Initialize the DP table
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(i):
                if nums[i - 1] & andValues[j - 1] == andValues[j - 1]:
                    dp[i][j] = min(dp[i][j], dp[k][j - 1] + nums[i - 1])

    return dp[n][m] if dp[n][m] != float('inf') else -1

