def digit_difference(nums):
    def digit_diff(a, b):
        return sum(1 for x, y in zip(str(a), str(b)) if x != y)

    total_diff = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            total_diff += digit_diff(nums[i], nums[j])
    return total_diff

def countWays(k):
    if k == 0:
        return 2
    if k == 1:
        return 4

    dp = [0] * (k + 1)
    dp[0] = 1

    for i in range(1, k + 1):
        dp[i] = dp[i - 1] + dp[i - 2]

    return dp[k]
